// Diff emits the test-delta facts.
func (p *Pane) Diff(before, after pane.Observation) (pane.Result, error) {
	base, ok := before.(*observation)
	if !ok {
		return pane.Result{}, fmt.Errorf("test-delta: base observation is %T", before)
	}
	res := pane.Result{Evidence: map[string]pane.Artifact{}}
	var lines []string

	p.sourceWithoutTest(&res, &lines)
	p.skipsAdded(base.Rev, &res, &lines)
	p.assertionsRemoved(base.Rev, &res, &lines)

	if len(res.Findings) == 0 {
		res.Confirmations = append(res.Confirmations, findings.Confirmation{
			Substrate: Substrate,
			Rule:      "tests-move-with-code",
			Message:   "every changed package changed a test, none were skipped or focused, and no assertions were removed",
		})
	}
	res.Render = pane.Render{
		Title:   "Tests",
		Summary: fmt.Sprintf("%d test-delta fact(s) from the diff", len(res.Findings)),
		Lines:   lines,
	}
	return res, nil
}

func TestSkipKind(t *testing.T) {
	skips := []string{
		"\tt.Skip(\"flaky\")",
		"    b.SkipNow()",
		"  it.skip('x', () => {})",
		"@pytest.mark.skip",
		"  self.skipTest('n')",
		"  xit('x', () => {})",
	}
	focus := []string{
		"  describe.only('x', () => {})",
		"  fit('x', () => {})",
	}
	none := []string{
		"\treturn nil",
		"\tt.Errorf(\"boom\")",
		"\t// skip this comment mentions skip but is not a directive",
	}
	for _, l := range skips {
		if got := skipKind(l); got != "skips a test" {
			t.Errorf("skipKind(%q) = %q, want a skip", l, got)
		}
	}
	for _, l := range focus {
		if got := skipKind(l); !strings.HasPrefix(got, "focuses") {
			t.Errorf("skipKind(%q) = %q, want a focus", l, got)
		}
	}
	for _, l := range none {
		if got := skipKind(l); got != "" {
			t.Errorf("skipKind(%q) = %q, want none", l, got)
		}
	}
}

func TestIsTestFile(t *testing.T) {
	yes := []string{
		"internal/foo/foo_test.go",
		"ui/src/a.test.ts",
		"ui/src/a.spec.tsx",
		"py/test_x.py",
		"py/x_test.py",
		"ui/src/__tests__/a.js",
	}
	no := []string{"internal/foo/foo.go", "ui/src/a.ts", "README.md", "py/x.py"}
	for _, f := range yes {
		if !isTestFile(f) {
			t.Errorf("isTestFile(%q) = false, want true", f)
		}
	}
	for _, f := range no {
		if isTestFile(f) {
			t.Errorf("isTestFile(%q) = true, want false", f)
		}
	}
}

func TestAssertionRe(t *testing.T) {
	match := []string{
		"\tassert.Equal(t, a, b)",
		"\trequire.NoError(t, err)",
		"\texpect(x).toBe(1)",
		"\tself.assertEqual(a, b)",
		"\tt.Fatal(\"no\")",
	}
	none := []string{"\tx := 1", "\treturn nil", "\t// assert something"}
	for _, l := range match {
		if !assertionRe.MatchString(l) {
			t.Errorf("assertionRe should match %q", l)
		}
	}
	for _, l := range none {
		if assertionRe.MatchString(l) {
			t.Errorf("assertionRe should not match %q", l)
		}
	}
}

// A Go package whose source changed with no test change in it is reported once;
// a package that also changed a test is not.
func TestSourceWithoutTest(t *testing.T) {
	p := &Pane{changed: []string{
		"internal/a/a.go",
		"internal/b/b.go",
		"internal/b/b_test.go",
		"README.md",
	}}
	var res pane.Result
	var lines []string
	p.sourceWithoutTest(&res, &lines)
	if len(res.Findings) != 1 {
		t.Fatalf("want 1 finding, got %d: %+v", len(res.Findings), res.Findings)
	}
	f := res.Findings[0]
	if f.Rule != "source-without-test" || f.Anchor == nil || f.Anchor.ID != "internal/a" {
		t.Fatalf("finding = %+v (anchor %+v)", f, f.Anchor)
	}
}

// Scope selects the changed code files. It also stashes the full changed set:
// the source-without-test fact must fire precisely when no test changed, and a
// pane with an empty scope never runs, so scope must be non-empty whenever code
// changed at all.
func (p *Pane) Scope(changed []string) []string {
	p.changed = changed
	var out []string
	for _, f := range changed {
		if hasExt(f, codeExts) {
			out = append(out, f)
		}
	}
	p.scoped = out
	return out
}

// Pane reports test-facing facts a diff shows on its own.
type Pane struct {
	Repo *gitx.Repo

	// changed is the whole changed set, kept for the source-without-test fact,
	// which is about files this pane does not otherwise open. scoped is the code
	// files it inspects line by line.
	changed []string
	scoped  []string
}

// Observe records the revision. Like the suppressions pane, the real work reads
// the diff in Diff, because every fact here is a property of added or removed
// lines rather than of a whole-file snapshot.
func (p *Pane) Observe(rev pane.Revision) (pane.Observation, error) {
	return &observation{Rev: rev.Rev}, nil
}

// DefaultSeverity derives a finding's severity from its category. Redline's
// categories all describe changes that alter a contract with something outside
// the diff, so they default to error; a pane may demote per finding.
func (c Category) DefaultSeverity() Severity {
	switch c {
	case CategorySchema, CategoryContract:
		return SeverityError
	case CategoryReview:
		return SeverityInfo
	case CategoryTests:
		return SeverityInfo
	default:
		return SeverityWarning
	}
}

// Run executes every applicable pane. Applicability is computed from the diff,
// never chosen by a caller: if the caller decides which checks to run, coverage
// becomes a sample from a distribution and a check can be silently skipped.
func Run(opts Options) (*Result, error) {
	tgt, err := target.Resolve(target.Options{
		Dir: opts.Dir, PR: opts.PR, Branch: opts.Branch,
		Commit: opts.Commit, Range: opts.Range, Base: opts.Base,
	})
	if err != nil {
		return nil, err
	}
	// Panes observe the target's directory. For a PR or a branch that is a
	// detached worktree at the head commit, so "the working tree" and "the
	// revision under review" are the same thing and no pane needs to know
	// which kind of target it is looking at.
	repo, err := gitx.Open(tgt.Dir)
	if err != nil {
		return nil, err
	}
	if tgt.Base != "" {
		opts.Base = tgt.Base
	}
	baseRef := resolveRef(repo, opts.Base)
	if baseRef == "" {
		return nil, fmt.Errorf("cannot determine a base revision: tried %s. "+
			"Pass --base REF, or make a first commit if this repository has none",
			strings.Join(defaultRefs, ", "))
	}
	baseSHA, err := repo.MergeBase(baseRef)
	if err != nil {
		return nil, fmt.Errorf("base %q: %w", baseRef, err)
	}
	changed, err := repo.ChangedPaths(baseSHA)
	if err != nil {
		return nil, err
	}
	changed = excludeOwnOutput(changed, opts.Out, repo.Root)

	// Generated output leaves the change here, before any pane or the report
	// sees it, so the coverage denominator counts files a reviewer would
	// actually read. What was dropped is recorded and shown: an exclusion the
	// reader cannot see is indistinguishable from a file that never changed.
	changed, generated := change.Generated(tgt.Dir, changed, repo.AttrSet("linguist-generated", changed))

	cfg, err := harness.Load(harnessConfigRoot(opts.Dir, tgt))
	if err != nil {
		return nil, err
	}
	configRoot := harnessConfigRoot(opts.Dir, tgt)
	prepared := map[string]bool{}
	roots := harness.Roots{Observe: tgt.Dir, Origin: originCoverageDir(opts.Dir, tgt), Caller: configRoot}
	if err := harness.Require(roots, changed, cfg, harness.RequireOpts{
		SkipCoverage: opts.AllowMissingCoverage,
	}); err != nil {
		return nil, err
	}
	if cfg != nil {
		if _, err := harness.PrepareWorktree(tgt.Dir, configRoot, changed, cfg, prepared); err != nil {
			return nil, err
		}
	}

	res := &Result{Evidence: map[string]pane.Artifact{}, Target: tgt, Report: findings.Report{
		BaseRef: baseRef,
		BaseSHA: baseSHA,
		Scope:   changed,
	}}

	panes := []pane.Pane{
		&migrations.Pane{Repo: repo, UpstreamRef: resolveRef(repo, opts.Upstream, baseRef), Dir: opts.MigDir},
		&openapi.Pane{Repo: repo},
		&lint.Delta{Repo: repo, Harness: cfg, HarnessRoot: configRoot, Prepared: prepared},
		&lint.Suppressions{Repo: repo},
		&lint.Config{Repo: repo},
		&testdelta.Pane{Repo: repo},
	}

	// Every path in the tree under review, listed once and only if a pane
	// turns out to have nothing in the change to look at. It answers a
	// different question from scope: not "does this pane apply to the change"
	// but "does this pane apply to the repository". A repository with no
	// migrations gets no mention of migrations; one whose migrations this
	// change did not touch is told so, quietly.
	var allPaths []string
	listAll := func() []string {
		if allPaths != nil {
			return allPaths
		}
		var blobs map[string]string
		var lerr error
		if tgt.Head == "" {
			blobs, lerr = repo.WorktreeBlobs()
		} else {
			blobs, lerr = repo.Blobs(tgt.Head)
		}
		if lerr != nil {
			// Unknown whether the pane applies: fall back to saying it was
			// skipped, the state that still gets a line on the report.
			allPaths = []string{}
			return allPaths
		}
		allPaths = make([]string, 0, len(blobs))
		for path := range blobs {
			allPaths = append(allPaths, path)
		}
		sort.Strings(allPaths)
		return allPaths
	}

	examined := map[string]bool{}
	for _, p := range panes {
		status := findings.SubstrateStatus{Name: p.Name()}
		scope := p.Scope(changed)
		for _, path := range scope {
			examined[path] = true
		}
		if len(scope) == 0 {
			// Scope over the whole tree is only consulted for a pane that will
			// not run, so the state it leaves behind in the pane is unused.
			if all := listAll(); len(all) > 0 && len(p.Scope(all)) == 0 {
				status.State = findings.SubstrateNotApplicable
				status.Detail = "the repository has no files this pane reads"
			} else {
				status.State = findings.SubstrateSkipped
				status.Detail = "this change touches none of the files this pane reads"
			}
			res.Report.Substrates = append(res.Report.Substrates, status)
			continue
		}
		out, err := runPane(p, baseSHA)
		if err != nil {
			// A pane that applied but did not run is recorded as failed and
			// as an unknown; it never reads as a pass.
			status.State = findings.SubstrateFailed
			status.Detail = err.Error()
			res.Report.Substrates = append(res.Report.Substrates, status)
			res.Report.Unknowns = append(res.Report.Unknowns, findings.Unknown{
				Substrate: p.Name(),
				Message:   "pane applied to this change but did not run",
				Reason:    err.Error(),
			})
			continue
		}
		status.State = findings.SubstrateRan
		res.Report.Substrates = append(res.Report.Substrates, status)
		res.Report.Findings = append(res.Report.Findings, out.Findings...)
		res.Report.Confirmations = append(res.Report.Confirmations, out.Confirmations...)
		res.Report.Unknowns = append(res.Report.Unknowns, out.Unknowns...)
		res.Renders = append(res.Renders, out.Render)
		for id, a := range out.Evidence {
			res.Evidence[id] = a
		}
	}

	res.Report.Coverage = coverage(changed, examined)
	res.Report.Coverage.Generated = generated
	res.Report.Unknowns = append(res.Report.Unknowns, unbuiltPanes(changed, examined)...)
	// The agent's review, if it has written one. Loaded before Finalize so its
	// line comments become findings that get fingerprints stamped with the rest;
	// verdicts merge after, joining on those fingerprints. Never fatal: a run
	// reports facts with or without a reading, and a broken file is stated.
	review, verr := findings.LoadReview(filepath.Join(opts.Out, "review.json"))
	if verr != nil {
		res.Report.Unknowns = append(res.Report.Unknowns, findings.Unknown{
			Substrate: "redline/review",
			Message:   "review.json was present but could not be read, so no agent review was merged",
			Reason:    verr.Error(),
		})
	}
	if review != nil {
		res.Report.Findings = append(res.Report.Findings, review.CommentFindings()...)
		if review.Overview != "" || len(review.Files) > 0 {
			res.Report.Agent = &findings.AgentReview{Overview: review.Overview, Files: review.Files}
		}
	}
	if res.Report.Coverage.ExaminedFiles == 0 && len(changed) > 0 {
		// No pane looked at any of it. This is not a clean review and must
		// never render as one. Stated after the agent's comments merge, so
		// the reason can be honest about whether the findings list is empty.
		reason := "this change is entirely unexamined; the empty findings list below is not evidence of correctness"
		if len(res.Report.Findings) > 0 {
			reason = "no pane covers these files; the findings below come from the agent's review"
		}
		res.Report.Unknowns = append(res.Report.Unknowns, findings.Unknown{
			Substrate: "redline",
			Message:   fmt.Sprintf("none of the %d changed file(s) fall under any pane Redline currently ships", len(changed)),
			Reason:    reason,
		})
	}
	res.Report.Finalize()
	if review != nil {
		res.Report.MergeVerdicts(review.Verdicts)
	}
	findings.Sort(res.Report.Findings)

	res.Change = change.Build(repo, tgt, baseSHA, changed)
	covDir := originCoverageDir(opts.Dir, tgt)
	attachDiffCoverage(&res.Report, res.Change, tgt.Dir, covDir, cfg)
	res.LineCoverage = lineCoverageOverlay(tgt.Dir, covDir, res.Change)
	attachMutation(&res.Report, res.Change, roots, cfg)
	return res, nil
}

// sourceWithoutTest names each Go package this change edits without touching a
// test in it. Go only: its one-test-file-per-package convention makes "a test in
// this package changed" a clean question, which JS and Python layouts do not
// answer as cleanly.
func (p *Pane) sourceWithoutTest(res *pane.Result, lines *[]string) {
	src := map[string]bool{}
	test := map[string]bool{}
	for _, f := range p.changed {
		if !strings.HasSuffix(f, ".go") {
			continue
		}
		dir := path.Dir(f)
		if strings.HasSuffix(f, "_test.go") {
			test[dir] = true
		} else {
			src[dir] = true
		}
	}
	var dirs []string
	for dir := range src {
		if !test[dir] {
			dirs = append(dirs, dir)
		}
	}
	sort.Strings(dirs)
	for _, dir := range dirs {
		res.Findings = append(res.Findings, findings.Finding{
			Anchor:    &findings.Anchor{Kind: "package", ID: dir},
			Rule:      "source-without-test",
			Substrate: Substrate,
			Category:  findings.CategoryTests,
			Severity:  findings.SeverityInfo,
			Message:   fmt.Sprintf("code in %s changed but no test in that package did", dir),
			Context:   "Not necessarily a problem: an existing test may already cover the change. Worth checking the new behavior has one.",
		})
		*lines = append(*lines, "~ "+dir+" (no test changed)")
	}
}

// skipsAdded reports a skip or focus directive on a line this change adds to a
// test file. A skip quietly removes a test from the run; a focus (.only, fit)
// quietly removes every other test in the file.
func (p *Pane) skipsAdded(baseRev string, res *pane.Result, lines *[]string) {
	for _, f := range p.scoped {
		if !isTestFile(f) {
			continue
		}
		added := map[int]bool{}
		for _, n := range cover.AddedLines(p.Repo.DiffPath(baseRev, f)) {
			added[n] = true
		}
		if len(added) == 0 {
			continue
		}
		content := p.Repo.File("", f)
		if content == "" {
			continue
		}
		for n, line := range strings.Split(content, "\n") {
			lineNo := n + 1
			if !added[lineNo] {
				continue
			}
			if what := skipKind(line); what != "" {
				res.Findings = append(res.Findings, findings.Finding{
					File:      f,
					Line:      lineNo,
					Rule:      "test-skip-added",
					Substrate: Substrate,
					Category:  findings.CategoryTests,
					Severity:  findings.SeverityInfo,
					Message:   "this change " + what,
					Observed:  strings.TrimSpace(line),
				})
				*lines = append(*lines, fmt.Sprintf("+ %s:%d %s", f, lineNo, what))
			}
		}
	}
}

// assertionsRemoved reports a test file that ends the change with fewer
// assertion-like lines than it started. Netting added against removed keeps a
// pure move or rename from reading as a loss; only a real drop is reported, and
// per file rather than per line, because a deleted line has no home in the head
// tree to anchor on.
func (p *Pane) assertionsRemoved(baseRev string, res *pane.Result, lines *[]string) {
	for _, f := range p.scoped {
		if !isTestFile(f) {
			continue
		}
		diff := p.Repo.DiffPath(baseRev, f)
		if diff == "" {
			continue
		}
		added, removed := 0, 0
		for _, l := range strings.Split(diff, "\n") {
			if strings.HasPrefix(l, "+++") || strings.HasPrefix(l, "---") {
				continue
			}
			switch {
			case strings.HasPrefix(l, "+"):
				if assertionRe.MatchString(l[1:]) {
					added++
				}
			case strings.HasPrefix(l, "-"):
				if assertionRe.MatchString(l[1:]) {
					removed++
				}
			}
		}
		if removed > added {
			res.Findings = append(res.Findings, findings.Finding{
				File:      f,
				Rule:      "assertions-removed",
				Substrate: Substrate,
				Category:  findings.CategoryTests,
				Severity:  findings.SeverityInfo,
				Message:   fmt.Sprintf("this change removes %d more assertion-like line(s) than it adds in this test", removed-added),
				Context:   "Assertions are what let a test fail. A net drop can mean a weaker test; check it is intended.",
			})
			*lines = append(*lines, fmt.Sprintf("- %s (-%d assertion-like line(s))", f, removed-added))
		}
	}
}

// isTestFile reports whether a path is a test file in a supported language.
func isTestFile(f string) bool {
	base := path.Base(f)
	switch {
	case strings.HasSuffix(f, "_test.go"):
		return true
	case strings.HasPrefix(base, "test_") && strings.HasSuffix(base, ".py"),
		strings.HasSuffix(base, "_test.py"):
		return true
	case strings.Contains(base, ".test.") || strings.Contains(base, ".spec."):
		return true
	case strings.Contains(f, "__tests__/"):
		return true
	}
	return false
}

// skipKind classifies a skip or focus directive, or returns "" for neither.
func skipKind(line string) string {
	switch {
	case focusRe.MatchString(line):
		return "focuses tests, so the others in the file will not run"
	case skipRe.MatchString(line):
		return "skips a test"
	}
	return ""
}

func hasExt(f string, exts []string) bool {
	for _, e := range exts {
		if strings.HasSuffix(f, e) {
			return true
		}
