// Result is everything a pane produces in one run.
type Result struct {
	Render        Render
	Findings      []findings.Finding
	Confirmations []findings.Confirmation
	Unknowns      []findings.Unknown

	// Evidence maps an observation ID to the artifact backing it — the SQL a
	// migration edit actually changed, a schema dump, a captured response.
	// Findings reference these by ID. A finding a reviewer cannot check for
	// themselves is inference wearing evidence's clothes.
	Evidence map[string]Artifact
}

// Revision names a side of the comparison. The working tree is a revision.
type Revision struct {
	Name string // "base" | "worktree"
	Rev  string // commit SHA, empty for the working tree
}

// Observation is one pane's view of the system at one revision. Panes that
// need a running system produce theirs by standing it up; panes that do not
// produce theirs by static extraction. The interface does not change.
type Observation interface {
	// ID identifies this observation for the Evidence field of a finding.
	ID() string
}

// Category classifies a finding. Redline adds its own categories rather than
// overloading doctor's — doctor's "api" means undeclared Go exported-API
// changes, which is a different thing from an HTTP contract change.
type Category string

// Options configures one run.
type Options struct {
	Dir      string // any directory inside the repository
	Base     string // base ref; merge-base with HEAD is used
	Upstream string // branch new migrations must not collide with
	MigDir   string // optional migrations directory filter

	// These point Redline at something other than the working tree.
	// Each is materialized as a detached worktree, so the user's own
	// checkout is never moved.
	PR     string
	Branch string
	Commit string
	Range  string
	Out    string // evidence directory; excluded from the change like .redline/

	// AllowMissingCoverage skips the fail-fast check for configured coverage
	// harness profiles. Other configured profiles (mutation, etc.) still apply.
	AllowMissingCoverage bool
}

// Result is a report plus the per-pane renders backing section 1 and the
// evidence artifacts findings point at.
type Result struct {
	Report   findings.Report
	Renders  []pane.Render
	Evidence map[string]pane.Artifact
	Target   *target.Target
	// Change is the file-by-file account of the diff the report renders its
	// walkthrough and drill-in sections from.
	Change *change.Set
	// LineCoverage overlays the profile onto the diff: per changed .go file,
	// each coverable line mapped to whether a test ran it. Nil when no profile.
	LineCoverage map[string]map[int]bool
}

// Config reports lint-configuration drift: a rule this change disables,
// downgrades, or newly excludes. A lint delta earned by turning a rule off
// looks identical to one earned by fixing code unless something names the
// rule, and this pane is that something.
//
// Enumeration is per format. golangci YAML and eslintrc JSON are parsed and
// their rule changes named; formats Redline cannot parse (a JS eslint config,
// a TOML golangci config) still produce a finding that the config changed,
// with the diff as evidence, so drift is never silent just because it is
// unparseable.
type Config struct {
	Repo *gitx.Repo

	scoped []string
}

// Delta runs the repository's configured linters at the base revision and at
// head, and reports the difference. This is the first pane that executes
// tools rather than reading git: the base side runs in a detached worktree at
// the base commit, the head side in the tree under review.
type Delta struct {
	Repo *gitx.Repo

	// tools caches detection, which reads the head tree. Detection is by the
	// head's config: the head defines what this repository lints with.
	tools     []tool
	detected  bool
	detectErr error

	// scoped is the changed files this pane examines, kept so Diff can run a
	// differ-kind tool (oasdiff) once per scoped file it covers.
	scoped []string

	// configChanged is set by Scope when the change touches a lint config. A
	// delta partly earned by editing the config has to say so: fewer findings
	// because a rule was turned off is not the same fact as fixed code.
	configChanged bool

	// Harness carries the run's .redline.yml config so this pane can run
	// harness.worktree steps (for example make stub-ui) in the base and head
	// trees before the linters read them. Set by run.Run, nil when there is no
	// config. Prepared is the run-scoped dedup set shared with the rest of the
	// run so a produce root runs at most once.
	Harness     *harness.Config
	HarnessRoot string
	Prepared    map[string]bool
}

// Suppressions collects every lint-silencing directive this change adds. It is
// the highest-signal lint fact a diff carries: the author explicitly told a
// linter to be quiet, and the reviewer should see where and about what.
//
// Only directives on lines the diff adds are reported. A directive that
// merely moved keeps its old justification; one the change introduces is the
// one that needs a fresh look. Findings are info severity: many silencings
// are legitimate, and the point is visibility, not a gate — a repository that
// wants them to block can list info in its profile.
type Suppressions struct {
	Repo *gitx.Repo

	// scoped is what Scope selected; Diff walks it.
	scoped []string
}

// Pane observes migration files at two revisions.
type Pane struct {
	Repo *gitx.Repo
	// UpstreamRef is the branch new migrations must not collide with,
	// typically origin/main.
	UpstreamRef string
	// Dir optionally restricts the pane to one migrations directory. Empty
	// means every path matching the golang-migrate naming convention.
	Dir string
}

// Pane diffs OpenAPI specs between two revisions.
type Pane struct {
	Repo *gitx.Repo
	// Paths is the set of spec files in the change, set by Scope.
	Paths []string
}

// snapshot is one revision's lint state: per tool, its issues or its failure.
type snapshot struct {
	Rev  string
	Runs []toolRun
}

// suppressObservation records the revision; the pane model observes whole
// revisions, but a directive is a fact about specific lines, so the real work
// reads the diff per scoped file in Diff.
type suppressObservation struct{ Rev string }

// Set is the migration files visible at one revision.
type Set struct {
	Rev   string
	Files map[string]string // path → blob SHA

	// UpstreamVersions is the set of migration versions already published on
	// the upstream branch, and is populated on the base-side observation only:
	// it is part of "what the world already has". UpstreamRef is empty and
	// UpstreamErr set when the upstream ref could not be read — which is an
	// unknown, never a pass.
	UpstreamVersions map[string]string // version → representative path upstream
	UpstreamRef      string
	UpstreamErr      string
}

// Observation is the parsed contract at one revision.
type Observation struct {
	// Side is "base" or "worktree"; Rev is the revision it resolved to, empty
	// for the working tree.
	Side  string
	Rev   string
	Specs map[string]*spec
}

// A Go package whose source changed with no test change in it is reported once;
// a package that also changed a test is not.
func TestSourceWithoutTest(t *testing.T) {
	p := &Pane{changed: []string{
		"internal/a/a.go",
		"internal/b/b.go",
		"internal/b/b_test.go",
		"README.md",
	}}
	var res pane.Result
	var lines []string
	p.sourceWithoutTest(&res, &lines)
	if len(res.Findings) != 1 {
		t.Fatalf("want 1 finding, got %d: %+v", len(res.Findings), res.Findings)
	}
	f := res.Findings[0]
	if f.Rule != "source-without-test" || f.Anchor == nil || f.Anchor.ID != "internal/a" {
		t.Fatalf("finding = %+v (anchor %+v)", f, f.Anchor)
	}
}

func (r *repo) run(opts run.Options) *run.Result {
	r.t.Helper()
	opts.Dir = r.dir
	res, err := run.Run(opts)
	if err != nil {
		r.t.Fatalf("run: %v", err)
	}
	return res
}

func TestAllowMissingCoverageContinuesWithHarness(t *testing.T) {
	r := baseline(t)
	r.write(".redline.yml", `harness:
  profiles:
    - id: go
      path: coverage.out
      produce: {command: true}
      when: stale
      scope: ["**/*.go"]
`)
	r.write("internal/x/x.go", "package x\n\nfunc A() int {\n\treturn 1\n}\n")

	res, err := run.Run(run.Options{Dir: r.dir, Base: "main", Upstream: "upstream", AllowMissingCoverage: true})
	if err != nil {
		t.Fatalf("allow-missing-coverage should continue: %v", err)
	}
	var found bool
	for _, u := range res.Report.Unknowns {
		if u.Substrate == "redline/tests" {
			found = true
		}
	}
	if !found {
		t.Fatal("expected coverage unknown on the report when allowed to continue")
	}
}

func TestMissingHarnessProfileBalks(t *testing.T) {
	r := baseline(t)
	r.write(".redline.yml", `harness:
  profiles:
    - id: go
      path: coverage.out
      produce: {command: true}
      when: stale
      scope: ["**/*.go"]
`)
	r.write("internal/x/x.go", "package x\n\nfunc A() int {\n\treturn 1\n}\n")

	_, err := run.Run(run.Options{Dir: r.dir, Base: "main", Upstream: "upstream"})
	if err == nil {
		t.Fatal("expected an error when a configured profile is missing")
	}
	if !strings.Contains(err.Error(), `harness profile "go"`) {
		t.Fatalf("unexpected error: %v", err)
	}
}

